// One calculation path for Home and Load/Wellness. No imputation of historical records.
export const ZONE='Europe/Madrid';
export const COVERAGE_THRESHOLD=.8; // Product choice, not a validated scientific threshold.
export function number(value){return value===null||value===undefined||value===''?null:Number.isFinite(Number(value))?Number(value):null;}
export function dayKey(value=new Date()){if(typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value))return value;const d=new Date(value);if(!Number.isFinite(+d))return null;return new Intl.DateTimeFormat('sv-SE',{timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(d);}
export function ordinal(value){const key=dayKey(value);return key?Date.parse(key+'T12:00:00Z')/86400000:null;}
export function shiftDay(value,days){return new Date(Date.parse(dayKey(value)+'T12:00:00Z')+days*86400000).toISOString().slice(0,10);}
export function madridInstant(date,time){const target=Date.parse(`${date}T${time}:00Z`);if(!Number.isFinite(target))throw Error('Fecha u hora no válidas');let stamp=target;for(let i=0;i<3;i++){const parts=Object.fromEntries(new Intl.DateTimeFormat('sv-SE',{timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(stamp)).map(p=>[p.type,p.value]));const local=Date.parse(`${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}Z`);stamp+=target-local;}const result=new Date(stamp);const check=new Intl.DateTimeFormat('sv-SE',{timeZone:ZONE,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(result);if(check!==time)throw Error('Esta hora no existe en Europe/Madrid; revisa el cambio horario.');return result.toISOString();}
export function sessionMinutes(event){const actual=number(event?.payload?.actual_duration_minutes);return event?.payload?.duration_confirmed===true&&actual>0?actual:null;}
export function scheduledMinutes(event){const value=(Date.parse(event?.ends_at)-Date.parse(event?.starts_at))/60000;return value>0?value:number(event?.payload?.duration);}
export function rpeWindow(event,now=Date.now(),override){const end=Date.parse(event?.ends_at);if(override&&Date.parse(override.expires_at)>now)return true;return Number.isFinite(end)&&now>=end+30*60000&&dayKey(now)===dayKey(event.starts_at);}
export function rpeReason(event,now,override){return rpeWindow(event,now,override)?'RPE disponible':'RPE: desde 30 min después del final hasta las 23:59 de ese día (Europe/Madrid), salvo reapertura del entrenador.';}
const present=new Set(['present','late']),absent=new Set(['justified','unjustified']);
export function buildLedger({events=[],attendance=[],rpes=[],exposures=[],contexts=[],player,now=Date.now()}){
 const att=new Map(attendance.filter(r=>r.player_id===player.id).map(r=>[r.event_id,r]));
 const records=new Map(exposures.filter(r=>r.player_id===player.id&&r.event_id).map(r=>[r.event_id,r]));
 const scores=new Map();for(const row of rpes.filter(r=>r.player_id===player.id&&r.source==='player')){const old=scores.get(row.event_id);if(!old||Date.parse(row.updated_at||row.created_at)>=Date.parse(old.updated_at||old.created_at))scores.set(row.event_id,row);}
 const children=new Set(events.map(e=>e.payload?.parent_tournament_id||e.payload?.tournament_id).filter(Boolean));
 const common=(row)=>{const reasons=[];const score=number(row.rpe),minutes=number(row.minutes);if(!row.validated)reasons.push('Participación pendiente de validar');if(!(minutes>0))reasons.push('Faltan minutos individuales fiables');if(!(score!==null&&score>=0&&score<=10))reasons.push('Falta RPE individual');if(!['self','player_relay','legacy_player'].includes(row.rpe_origin)&&score!==null)reasons.push('RPE estimado por el entrenador o procedencia no confirmada');return {...row,reasons,state:reasons.length?'incomplete':'complete',load:reasons.length?null:score*minutes};};
 const ledger=[];
 for(const event of events){if(!['training','match','friendly','tournament'].includes(event.event_type)||['cancelled','canceled','deleted'].includes(event.status)||Date.parse(event.starts_at)>now)continue;if(event.ends_at&&Date.parse(event.ends_at)>now)continue;if(player.created_at&&ordinal(event.starts_at)<ordinal(player.created_at))continue;
  const row=records.get(event.id),a=att.get(event.id),r=scores.get(event.id);const canonicalNewer=!!r;const base={id:event.id,event_id:event.id,date:dayKey(event.starts_at),title:event.title,type:event.event_type,event,record:row,attendance:a,rpeRow:r};
  if(event.event_type==='tournament'&&(children.has(event.id)||event.payload?.load_container===true)){ledger.push({...base,state:'container',load:null,reasons:['Torneo contenedor: se cuentan sus partidos, no el torneo de nuevo']});continue;}
  if(!row&&!a&&contexts.some(c=>c.player_id===player.id&&c.no_exposure_confirmed&&c.starts_on<=base.date&&c.ends_on>=base.date)){ledger.push({...base,state:'rest',load:null,reasons:['Sin exposición confirmada en el contexto del periodo']});continue;}
  if(row?.participation==='rest'&&row.validated||!row&&absent.has(a?.official_status)&&a?.validated_at){ledger.push({...base,state:'rest',load:null,reasons:['Sin exposición confirmada']});continue;}
  const participated=row?.participation==='participated'||!row&&present.has(a?.official_status);
  let minutes=row?number(row.minutes):number(a?.effective_minutes);if(!row&&minutes===null&&a?.official_status==='present'&&event.event_type==='training')minutes=sessionMinutes(event);
  ledger.push(common({...base,participated,validated:row?row.validated&&participated:!!a?.validated_at&&participated,minutes,rpe:canonicalNewer?r.score:row?row.rpe:r?.score,rpe_origin:canonicalNewer?'legacy_player':row?row.rpe_origin:r?'legacy_player':null,volleyball:row?{jumps:row.jumps,strikes:row.strikes,kind:row.count_kind}:null}));
 }
 for(const row of exposures.filter(r=>r.player_id===player.id&&!r.event_id&&ordinal(r.occurred_on)<=ordinal(now))){const base={...row,id:row.id,date:row.occurred_on,record:row,type:'additional',participated:row.participation==='participated'};ledger.push(row.participation==='rest'&&row.validated?{...base,state:'rest',load:null,reasons:['Sin exposición confirmada']}:common(base));}
 return ledger.sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id));
}
function coversRest(contexts,start,end){return contexts.some(c=>c.no_exposure_confirmed&&c.starts_on<=start&&c.ends_on>=end);}
export function periodSummary(ledger,start,end,contexts=[]){const rows=ledger.filter(r=>r.date>=start&&r.date<=end&&r.state!=='container');const completed=rows.filter(r=>r.state==='complete'),participated=rows.filter(r=>r.participated),pending=rows.filter(r=>r.state==='incomplete');const rest=rows.filter(r=>r.state==='rest');const confirmedEmpty=!rows.length&&coversRest(contexts,start,end);const known=rows.length>0||confirmedEmpty;return {start,end,rows,load:completed.reduce((n,r)=>n+r.load,0),completed:completed.length,performed:participated.length,pending:pending.length,unknownParticipation:pending.filter(r=>!r.validated).length,rest:rest.length,known,confirmedEmpty,complete:known&&!pending.length,coverage:participated.length?completed.length/participated.length:confirmedEmpty||rest.length&&!pending.length?1:0};}
export function summarize(input){const {now=Date.now(),contexts=[],wellness=[]}=input;const today=dayKey(now),ledger=buildLedger(input),ownContexts=contexts.filter(c=>c.player_id===input.player.id);const weeks=Array.from({length:5},(_,i)=>{const back=4-i;return periodSummary(ledger,shiftDay(today,-6-back*7),shiftDay(today,-back*7),ownContexts)});const current=weeks[4],base=weeks.slice(0,4),reasons=[];if(base.some(w=>!w.known))reasons.push('Hay semanas sin registros ni descanso confirmado');if(base.some(w=>w.unknownParticipation))reasons.push('Hay asistencias sin validar en la referencia');if(base.some(w=>w.coverage<COVERAGE_THRESHOLD))reasons.push('Cobertura inferior al 80% en alguna semana de referencia (criterio de producto)');if(input.player.created_at&&dayKey(input.player.created_at)>base[0].start)reasons.push('La jugadora aún no dispone de todo el periodo de referencia');const context=ownContexts.filter(c=>c.starts_on<=today&&c.ends_on>=base[0].start);if(context.some(c=>['vacation','illness','injury','return'].includes(c.kind)))reasons.push('Vacaciones, enfermedad, lesión o retorno afectan a este periodo');const reference=reasons.length?null:base.reduce((n,w)=>n+w.load,0)/4;if(reference===0)reasons.push('La referencia no tiene carga registrada positiva');const usable=reference>0&&!reasons.length;const change=usable&&current.complete?(current.load/reference-1)*100:null;const message=!current.complete?'Faltan registros':!usable?'Referencia insuficiente':Math.abs(change)<=15?'Similar a lo habitual':change>0?'Más exigente que tus semanas anteriores':'Menor carga registrada que tus semanas anteriores';
 const entries=wellness.filter(w=>w.player_id===input.player.id&&w.entry_date<=today).slice().sort((a,b)=>b.entry_date.localeCompare(a.entry_date));const latest=entries[0]||null,previous=entries[1]||null;const notices=[];if(current.pending)notices.push(`${current.pending} actividades con datos incompletos`);if(latest&&previous&&number(latest.pain_score)>number(previous.pain_score))notices.push(`Dolor en aumento: ${previous.pain_score} → ${latest.pain_score}/10 (${previous.entry_date} → ${latest.entry_date}). Habla con la jugadora.`);if(latest&&previous&&(number(latest.fatigue)>number(previous.fatigue)||number(latest.sleep)<number(previous.sleep)))notices.push('Fatiga o sueño han empeorado respecto al último registro. Revisar sensaciones.');if(latest&&latest.training_limitation&&latest.training_limitation!=='none')notices.push('La jugadora comunica limitación para entrenar. Revisar y hablar con ella.');if(!latest||latest.entry_date!==today)notices.push('Bienestar de hoy pendiente; el último dato no describe necesariamente el estado actual.');return {today,ledger,weeks,current,reference:usable?reference:null,referenceReasons:reasons,message,change,ratio:usable&&current.complete?current.load/reference:null,latest,previous,notices,context};
}
